 1→package jlsm.table;
 2→
 3→import java.util.Objects;
 4→
 5→/**
 6→ * Defines a named field and its type within a {@link JlsmSchema}.
 7→ *
 8→ * @param name the field name; must not be null
 9→ * @param type the field type; must not be null
10→ * @param encryption the encryption specification for this field; must not be null
11→ */
12→public record FieldDefinition(String name, FieldType type, EncryptionSpec encryption) {
13→
14→    /**
15→     * Compact constructor — validates all components are non-null.
16→     */
17→    public FieldDefinition {
18→        Objects.requireNonNull(name, "name must not be null");
19→        Objects.requireNonNull(type, "type must not be null");
20→        Objects.requireNonNull(encryption, "encryption must not be null");
21→    }
22→
23→    /**
24→     * Backward-compatible constructor that defaults encryption to {@link EncryptionSpec#NONE}.
25→     *
26→     * @param name the field name; must not be null
27→     * @param type the field type; must not be null
28→     */
29→    public FieldDefinition(String name, FieldType type) {
30→        this(name, type, EncryptionSpec.NONE);
31→    }
32→}
