  3→import java.nio.ByteBuffer;
  4→import java.security.SecureRandom;
  5→import java.util.Objects;
  6→import java.util.Random;
  7→
  8→/**
  9→ * Contract: Distance-comparison-preserving encryption using Scale-And-Perturb (SAP). Encrypts a
 10→ * {@code float[]} vector to a {@code float[]} of the same dimensionality, approximately preserving
 11→ * distance relationships so that existing HNSW/IVF indexes work on encrypted vectors.
 12→ *
 13→ * <p>
 14→ * Encryption: {@code c = s * v + noise}, where {@code s} is a scaling factor derived from the key
 15→ * and {@code noise} is sampled from a d-ball using a per-vector perturbation seed. Decryption
 16→ * requires the stored seed to reconstruct the noise vector.
 17→ *
 18→ * <p>
 19→ * Governed by: .kb/algorithms/encryption/vector-encryption-approaches.md
 20→ */
 21→public final class DcpeSapEncryptor {
 22→
 23→    private final double scaleFactor;
 24→    private final int dimensions;
 25→    private final byte[] keyBytes;
 26→    private final SecureRandom seedRng;
 27→
 28→    /**
 29→     * Creates a DCPE Scale-And-Perturb encryptor with the given key.
 30→     *
 31→     * @param keyHolder the key holder providing key material
 32→     * @param dimensions the expected vector dimensionality; must be positive
 33→     * @throws IllegalArgumentException if dimensions is not positive
 34→     */
 35→    public DcpeSapEncryptor(EncryptionKeyHolder keyHolder, int dimensions) {
 36→        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
 37→        if (dimensions <= 0) {
 38→            throw new IllegalArgumentException("dimensions must be positive, got " + dimensions);
 39→        }
 40→        this.dimensions = dimensions;
 41→        this.keyBytes = keyHolder.getKeyBytes();
 42→
 43→        // Derive scaling factor from key: hash first 8 bytes to a positive double in [1.5, 3.5)
 44→        final long keyLong = ByteBuffer.wrap(keyBytes, 0, 8).getLong();
 45→        this.scaleFactor = 1.5 + 2.0 * ((double) (keyLong >>> 1) / (double) Long.MAX_VALUE);
 46→        assert scaleFactor >= 1.5 && scaleFactor < 3.5 : "scaleFactor out of expected range";
 47→
 48→        // Seed RNG from remaining key bytes for generating per-vector seeds
 49→        this.seedRng = new SecureRandom(keyBytes);
 50→    }
 51→
 52→    /**
 53→     * Encrypts a plaintext vector, preserving approximate distance relationships.
 54→     *
 55→     * @param vector the plaintext vector; must have length equal to configured dimensions
 56→     * @return the encrypted vector and its perturbation seed
 57→     * @throws IllegalArgumentException if vector length does not match dimensions
 58→     */
 59→    public EncryptedVector encrypt(float[] vector) {
 60→        Objects.requireNonNull(vector, "vector must not be null");
 61→        if (vector.length != dimensions) {
 62→            throw new IllegalArgumentException(
 63→                    "Vector length must be " + dimensions + ", got " + vector.length);
 64→        }
 65→
 66→        final long seed = seedRng.nextLong();
 67→        final float[] noise = generateNoise(seed);
 68→
 69→        final float[] encrypted = new float[dimensions];
 70→        for (int i = 0; i < dimensions; i++) {
 71→            encrypted[i] = (float) (scaleFactor * vector[i]) + noise[i];
 72→        }
 73→
 74→        return new EncryptedVector(encrypted, seed);
 75→    }
 76→
 77→    /**
 78→     * Decrypts an encrypted vector using the stored perturbation seed.
 79→     *
 80→     * @param encrypted the encrypted vector values
 81→     * @param seed the perturbation seed stored during encryption
 82→     * @return the reconstructed plaintext vector
 83→     */
 84→    public float[] decrypt(float[] encrypted, long seed) {
 85→        Objects.requireNonNull(encrypted, "encrypted must not be null");
 86→        final float[] noise = generateNoise(seed);
 87→
 88→        final float[] result = new float[encrypted.length];
 89→        for (int i = 0; i < encrypted.length; i++) {
 90→            result[i] = (float) ((encrypted[i] - noise[i]) / scaleFactor);
 91→        }
 92→        return result;
 93→    }
 94→
 95→    /**
 96→     * Generates a noise vector sampled from the d-ball using a deterministic seed. The perturbation
 97→     * radius beta is kept small (0.01) to maintain distance ordering.
 98→     */
 99→    private float[] generateNoise(long seed) {
100→        final double beta = 0.01;
101→        final Random rng = new Random(seed);
102→
103→        // Sample from d-dimensional unit ball using Gaussian method:
104→        // 1. Sample d Gaussian values
105→        // 2. Normalize to unit sphere
106→        // 3. Scale by uniform radius^(1/d) * beta
107→        final float[] noise = new float[dimensions];
108→        double normSq = 0.0;
109→        for (int i = 0; i < dimensions; i++) {
110→            final double g = rng.nextGaussian();
111→            noise[i] = (float) g;
112→            normSq += g * g;
113→        }
114→
115→        final double norm = Math.sqrt(normSq);
116→        if (norm > 0) {
117→            // Uniform radius in d-ball: r = U^(1/d) * beta
118→            final double u = rng.nextDouble();
119→            final double r = Math.pow(u, 1.0 / dimensions) * beta;
120→
121→            for (int i = 0; i < dimensions; i++) {
122→                noise[i] = (float) (noise[i] / norm * r);
123→            }
124→        }
125→
126→        return noise;
127→    }
128→
129→    /**
130→     * Holds an encrypted vector alongside the perturbation seed needed for decryption.
131→     *
132→     * @param values the encrypted vector components (same dimensionality as plaintext)
133→     * @param seed the perturbation seed used during encryption
134→     */
135→    public record EncryptedVector(float[] values, long seed) {
136→    }
137→}
