  1→package jlsm.table.internal;
  2→
  3→import java.security.GeneralSecurityException;
  4→import java.security.SecureRandom;
  5→import java.util.Arrays;
  6→import java.util.Objects;
  7→
  8→import javax.crypto.Cipher;
  9→import javax.crypto.spec.GCMParameterSpec;
 10→import javax.crypto.spec.SecretKeySpec;
 11→
 12→/**
 13→ * Contract: Opaque encryption using AES-GCM with a random IV per encryption. Provides authenticated
 14→ * encryption — tampering or wrong-key decryption is detected via tag verification. No search
 15→ * capability on encrypted values.
 16→ *
 17→ * <p>
 18→ * Ciphertext format: {@code [12-byte IV || ciphertext || 16-byte auth tag]} — +28 bytes expansion.
 19→ *
 20→ * <p>
 21→ * Governed by: .kb/algorithms/encryption/searchable-encryption-schemes.md
 22→ */
 23→public final class AesGcmEncryptor {
 24→
 25→    private static final int IV_LENGTH = 12;
 26→    private static final int TAG_BITS = 128;
 27→    private static final int TAG_BYTES = TAG_BITS / 8;
 28→    private static final int OVERHEAD = IV_LENGTH + TAG_BYTES;
 29→    private static final String ALGORITHM = "AES/GCM/NoPadding";
 30→
 31→    private final byte[] keyBytes;
 32→    private final SecureRandom random;
 33→
 34→    /**
 35→     * Creates an AES-GCM encryptor using the given key holder.
 36→     *
 37→     * @param keyHolder the key holder providing a 256-bit (32-byte) key
 38→     * @throws IllegalArgumentException if key length is not 32 bytes
 39→     */
 40→    public AesGcmEncryptor(EncryptionKeyHolder keyHolder) {
 41→        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
 42→        if (keyHolder.keyLength() != 32) {
 43→            throw new IllegalArgumentException(
 44→                    "AES-GCM requires a 256-bit (32-byte) key, got " + keyHolder.keyLength());
 45→        }
 46→        this.keyBytes = keyHolder.getKeyBytes();
 47→        this.random = new SecureRandom();
 48→    }
 49→
 50→    /**
 51→     * Encrypts the plaintext with AES-GCM using a random IV.
 52→     *
 53→     * @param plaintext the data to encrypt; must not be null
 54→     * @return the ciphertext as {@code [12-byte IV || encrypted bytes || 16-byte tag]}
 55→     */
 56→    public byte[] encrypt(byte[] plaintext) {
 57→        Objects.requireNonNull(plaintext, "plaintext must not be null");
 58→        try {
 59→            final byte[] iv = new byte[IV_LENGTH];
 60→            random.nextBytes(iv);
 61→
 62→            final Cipher cipher = Cipher.getInstance(ALGORITHM);
 63→            final SecretKeySpec keySpec = new SecretKeySpec(keyBytes, "AES");
 64→            final GCMParameterSpec gcmSpec = new GCMParameterSpec(TAG_BITS, iv);
 65→            cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec);
 66→
 67→            final byte[] encrypted = cipher.doFinal(plaintext);
 68→            // encrypted = ciphertext || tag (GCM appends the tag)
 69→            assert encrypted.length == plaintext.length + TAG_BYTES : "GCM output length mismatch";
 70→
 71→            final byte[] result = new byte[IV_LENGTH + encrypted.length];
 72→            System.arraycopy(iv, 0, result, 0, IV_LENGTH);
 73→            System.arraycopy(encrypted, 0, result, IV_LENGTH, encrypted.length);
 74→            return result;
 75→        } catch (GeneralSecurityException e) {
 76→            throw new IllegalStateException("AES-GCM encryption failed", e);
 77→        }
 78→    }
 79→
 80→    /**
 81→     * Decrypts AES-GCM ciphertext and verifies the authentication tag.
 82→     *
 83→     * @param ciphertext the data to decrypt (IV || encrypted || tag); must not be null
 84→     * @return the plaintext bytes
 85→     * @throws IllegalArgumentException if ciphertext is too short
 86→     * @throws SecurityException if authentication tag verification fails
 87→     */
 88→    public byte[] decrypt(byte[] ciphertext) {
 89→        Objects.requireNonNull(ciphertext, "ciphertext must not be null");
 90→        if (ciphertext.length < OVERHEAD) {
 91→            throw new IllegalArgumentException("Ciphertext too short: minimum " + OVERHEAD
 92→                    + " bytes, got " + ciphertext.length);
 93→        }
 94→        try {
 95→            final byte[] iv = Arrays.copyOfRange(ciphertext, 0, IV_LENGTH);
 96→            final byte[] encrypted = Arrays.copyOfRange(ciphertext, IV_LENGTH, ciphertext.length);
 97→
 98→            final Cipher cipher = Cipher.getInstance(ALGORITHM);
 99→            final SecretKeySpec keySpec = new SecretKeySpec(keyBytes, "AES");
100→            final GCMParameterSpec gcmSpec = new GCMParameterSpec(TAG_BITS, iv);
101→            cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec);
102→
103→            return cipher.doFinal(encrypted);
104→        } catch (javax.crypto.AEADBadTagException e) {
105→            throw new SecurityException("AES-GCM authentication failed: wrong key or tampered data",
106→                    e);
107→        } catch (GeneralSecurityException e) {
108→            throw new SecurityException("AES-GCM decryption failed", e);
109→        }
110→    }
111→}
