 7→/**
 8→ * Defines a secondary index on a table field.
 9→ *
10→ * <p>
11→ * Contract:
12→ * <ul>
13→ * <li>Receives: field name, index type, and optional similarity function for vector indices</li>
14→ * <li>Returns: immutable definition used by the table builder to create the index</li>
15→ * <li>Side effects: none — pure value holder</li>
16→ * <li>Validated at table build time against the schema</li>
17→ * </ul>
18→ *
19→ * <p>
20→ * Vector dimensions are derived from the schema's {@link FieldType.VectorType} at
21→ * {@link jlsm.table.internal.IndexRegistry} construction time, not stored here.
22→ *
23→ * @param fieldName the schema field to index — must exist in the table's schema
24→ * @param indexType the type of index to create
25→ * @param similarityFunction similarity function for VECTOR indices; null for other types
26→ */
27→public record IndexDefinition(String fieldName, IndexType indexType,
28→        SimilarityFunction similarityFunction) {
29→
30→    /**
31→     * Creates an index definition for non-vector index types.
32→     */
33→    public IndexDefinition(String fieldName, IndexType indexType) {
34→        this(fieldName, indexType, null);
35→    }
36→
37→    public IndexDefinition {
38→        Objects.requireNonNull(fieldName, "fieldName");
39→        Objects.requireNonNull(indexType, "indexType");
40→        if (fieldName.isBlank()) {
41→            throw new IllegalArgumentException("fieldName must not be blank");
42→        }
43→        if (indexType == IndexType.VECTOR) {
44→            Objects.requireNonNull(similarityFunction,
45→                    "similarityFunction required for VECTOR indices");
46→        }
47→    }
48→}
