  2→
  3→import jlsm.core.io.MemorySerializer;
  4→import jdk.incubator.vector.ByteVector;
  5→import jdk.incubator.vector.DoubleVector;
  6→import jdk.incubator.vector.FloatVector;
  7→import jdk.incubator.vector.IntVector;
  8→import jdk.incubator.vector.LongVector;
  9→import jdk.incubator.vector.VectorShuffle;
 10→import jdk.incubator.vector.VectorSpecies;
 11→
 12→import java.lang.foreign.MemorySegment;
 13→import java.lang.foreign.ValueLayout;
 14→import java.nio.charset.StandardCharsets;
 15→import java.util.List;
 16→import java.util.Objects;
 17→import java.util.Optional;
 18→
 19→/**
 20→ * Binary serializer for {@link JlsmDocument} values.
 21→ *
 22→ * <p>
 23→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 24→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 25→ *
 26→ * <p>
 27→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 28→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 29→ * {@code null}.
 30→ *
 31→ * <p>
 32→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 33→ * {@code jdk.incubator.vector}.
 34→ */
 35→public final class DocumentSerializer {
 36→
 37→    private DocumentSerializer() {
 38→    }
 39→
 40→    /**
 41→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 42→     * schema.
 43→     *
 44→     * @param schema the schema describing the document structure; must not be null
 45→     * @return a MemorySerializer for JlsmDocument
 46→     */
 47→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 48→        Objects.requireNonNull(schema, "schema must not be null");
 49→        return new SchemaSerializer(schema);
 50→    }
 51→
 52→    // =========================================================================
 53→    // Implementation
 54→    // =========================================================================
 55→
 56→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 57→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 58→
 59→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 60→    private static final VectorShuffle<Byte> BSWAP32;
 61→
 62→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 63→    private static final VectorShuffle<Byte> BSWAP64;
 64→
 65→    static {
 66→        final int byteLen = BYTE_SPECIES.length();
 67→        final int[] idx32 = new int[byteLen];
 68→        final int[] idx64 = new int[byteLen];
 69→        for (int i = 0; i + 3 < byteLen; i += 4) {
 70→            idx32[i + 0] = i + 3;
 71→            idx32[i + 1] = i + 2;
 72→            idx32[i + 2] = i + 1;
 73→            idx32[i + 3] = i + 0;
 74→        }
 75→        for (int i = 0; i + 7 < byteLen; i += 8) {
 76→            idx64[i + 0] = i + 7;
 77→            idx64[i + 1] = i + 6;
 78→            idx64[i + 2] = i + 5;
 79→            idx64[i + 3] = i + 4;
 80→            idx64[i + 4] = i + 3;
 81→            idx64[i + 5] = i + 2;
 82→            idx64[i + 6] = i + 1;
 83→            idx64[i + 7] = i + 0;
 84→        }
 85→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
 86→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
 87→    }
 88→
 89→    // -------------------------------------------------------------------------
 90→    // Serializer implementation
 91→    // -------------------------------------------------------------------------
 92→
 93→    /** Decodes a single non-boolean, non-null field from a byte array at the cursor position. */
 94→    @FunctionalInterface
 95→    private interface FieldDecoder {
 96→        Object decode(byte[] buf, Cursor cursor);
 97→    }
 98→
 99→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
100→
101→        private final JlsmSchema schema;
102→        private final boolean[] isBoolField;
103→        private final int[] prefixBoolCount;
104→        private final int fieldCount;
105→        private final int boolCount;
106→        private final int nullMaskBytes;
107→        private final int boolMaskBytes;
108→        private final FieldDecoder[] decoders;
109→
110→        SchemaSerializer(JlsmSchema schema) {
111→            this.schema = schema;
112→
113→            final List<FieldDefinition> fields = schema.fields();
114→            this.fieldCount = fields.size();
115→            final FieldDefinition[] fieldArray = fields.toArray(new FieldDefinition[0]);
116→
117→            // Precompute boolean field flags and prefix counts
118→            this.isBoolField = new boolean[fieldCount];
119→            this.prefixBoolCount = new int[fieldCount + 1];
120→            int bools = 0;
121→            for (int i = 0; i < fieldCount; i++) {
122→                prefixBoolCount[i] = bools;
123→                if (fieldArray[i].type() == FieldType.Primitive.BOOLEAN) {
124→                    isBoolField[i] = true;
125→                    bools++;
126→                }
127→            }
128→            prefixBoolCount[fieldCount] = bools;
129→            this.boolCount = bools;
130→
131→            this.nullMaskBytes = (fieldCount + 7) / 8;
132→            this.boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
133→
134→            // Build dispatch table for non-boolean field decoders
135→            this.decoders = new FieldDecoder[fieldCount];
136→            for (int i = 0; i < fieldCount; i++) {
137→                if (!isBoolField[i]) {
138→                    final FieldType type = fieldArray[i].type();
139→                    decoders[i] = (buf, cursor) -> decodeField(buf, cursor, type);
140→                }
141→            }
142→        }
143→
144→        @Override
145→        public MemorySegment serialize(JlsmDocument doc) {
146→            Objects.requireNonNull(doc, "doc must not be null");
147→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
148→                    : "document schema mismatch";
149→
150→            final List<FieldDefinition> fields = schema.fields();
151→            final int fieldCount = fields.size();
152→            final Object[] values = doc.values();
153→
154→            // Count boolean fields
155→            final int boolCount = countBoolFields(fields);
156→
157→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
158→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
159→            final int nullMaskBytes = (fieldCount + 7) / 8;
160→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
161→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
162→
163→            // Two-pass: measure then encode
164→            final int payloadSize = measureFields(fields, values);
165→            final int totalSize = headerSize + payloadSize;
166→
167→            final byte[] buf = new byte[totalSize];
168→
169→            // Write header
170→            writeShortBE(buf, 0, (short) schema.version());
171→            writeShortBE(buf, 2, (short) fieldCount);
172→            // Null bitmask
173→            buildNullMask(fields, values, buf, 4);
174→            // Boolean bitmask
175→            if (boolCount > 0) {
176→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
177→            }
178→
179→            // Write values
180→            final Cursor cursor = new Cursor(buf, headerSize);
181→            encodeFields(fields, values, cursor);
182→
183→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
184→            return MemorySegment.ofArray(buf);
185→        }
186→
187→        @Override
188→        public JlsmDocument deserialize(MemorySegment segment) {
189→            Objects.requireNonNull(segment, "segment must not be null");
190→
191→            final ByteArrayView view = extractBytes(segment);
192→            final byte[] buf = view.data();
193→            final Cursor cursor = new Cursor(buf, view.offset());
194→
195→            // Read header
196→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
197→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
198→
199→            // We only read min(writeFieldCount, currentFieldCount) fields
200→            final int readCount = Math.min(writeFieldCount, fieldCount);
201→
202→            // Use precomputed prefixBoolCount for O(1) lookup instead of O(n) iteration
203→            final int writeBoolCount = prefixBoolCount[readCount];
204→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
205→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
206→
207→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
208→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
209→
210→            // Decode values
211→            final Object[] values = new Object[fieldCount];
212→            // Fields beyond readCount remain null (new fields added in a later schema version)
213→
214→            int boolIdx = 0;
215→            for (int i = 0; i < readCount; i++) {
216→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
217→                if (isNull) {
218→                    if (isBoolField[i]) {
219→                        boolIdx++;
220→                    }
221→                    continue;
222→                }
223→                if (isBoolField[i]) {
224→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
225→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
226→                    boolIdx++;
227→                } else {
228→                    values[i] = decoders[i].decode(buf, cursor);
229→                }
230→            }
231→
232→            return new JlsmDocument(schema, values);
233→        }
234→    }
235→
236→    // =========================================================================
237→    // Measure helpers (first pass)
238→    // =========================================================================
239→
240→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
241→        int total = 0;
242→        for (int i = 0; i < fields.size(); i++) {
243→            final FieldDefinition fd = fields.get(i);
244→            final Object val = values[i];
245→            if (val == null) {
246→                continue; // null → no value bytes
247→            }
248→            total += measureField(fd.type(), val);
249→        }
250→        return total;
251→    }
252→
253→    private static int measureField(FieldType type, Object value) {
254→        return switch (type) {
255→            case FieldType.Primitive p -> switch (p) {
256→                case STRING -> {
257→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
258→                    yield varIntSize(utf8.length) + utf8.length;
259→                }
260→                case INT8 -> 1;
261→                case INT16 -> 2;
262→                case INT32 -> 4;
263→                case INT64 -> 8;
264→                case FLOAT16 -> 2;
265→                case FLOAT32 -> 4;
266→                case FLOAT64 -> 8;
267→                case BOOLEAN -> 0; // packed in bitmask
268→                case TIMESTAMP -> 8;
269→            };
270→            case FieldType.ArrayType at -> {
271→                final Object[] arr = (Object[]) value;
272→                int sz = varIntSize(arr.length);
273→                for (Object elem : arr) {
274→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
275→                }
276→                yield sz;
277→            }
278→            case FieldType.VectorType vt -> {
279→                final int elemBytes = vt.elementType() == FieldType.Primitive.FLOAT32 ? 4 : 2;
280→                yield vt.dimensions() * elemBytes;
281→            }
282→            case FieldType.ObjectType ot -> {
283→                final JlsmDocument sub = (JlsmDocument) value;
284→                final List<FieldDefinition> subFields = ot.fields();
285→                final int subBoolCount = countBoolFields(subFields);
286→                final int subNullBytes = (subFields.size() + 7) / 8;
287→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
288→                int sz = subNullBytes + subBoolBytes;
289→                sz += measureFields(subFields, sub.values());
290→                yield sz;
291→            }
292→        };
293→    }
294→
295→    // =========================================================================
296→    // Encode helpers (second pass)
297→    // =========================================================================
298→
299→    private static void encodeFields(List<FieldDefinition> fields, Object[] values, Cursor c) {
300→        for (int i = 0; i < fields.size(); i++) {
301→            final Object val = values[i];
302→            if (val == null) {
303→                continue;
304→            }
305→            encodeField(c, fields.get(i).type(), val);
306→        }
307→    }
308→
309→    private static void encodeField(Cursor c, FieldType type, Object value) {
310→        switch (type) {
311→            case FieldType.Primitive p -> {
312→                switch (p) {
313→                    case STRING -> {
314→                        final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
315→                        writeVarInt(c, utf8.length);
316→                        System.arraycopy(utf8, 0, c.buf, c.pos, utf8.length);
317→                        c.pos += utf8.length;
318→                    }
319→                    case INT8 -> c.buf[c.pos++] = (Byte) value;
320→                    case INT16 -> {
321→                        writeShortBE(c.buf, c.pos, (Short) value);
322→                        c.pos += 2;
323→                    }
324→                    case INT32 -> {
325→                        writeIntBE(c.buf, c.pos, (Integer) value);
326→                        c.pos += 4;
327→                    }
328→                    case INT64 -> {
329→                        writeLongBE(c.buf, c.pos, (Long) value);
330→                        c.pos += 8;
331→                    }
332→                    case FLOAT16 -> {
333→                        writeShortBE(c.buf, c.pos, (Short) value);
334→                        c.pos += 2;
335→                    }
336→                    case FLOAT32 -> {
337→                        writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) value));
338→                        c.pos += 4;
339→                    }
340→                    case FLOAT64 -> {
341→                        writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) value));
342→                        c.pos += 8;
343→                    }
344→                    case BOOLEAN -> {
345→                        // Boolean values are packed in the bool bitmask; nothing here
346→                    }
347→                    case TIMESTAMP -> {
348→                        writeLongBE(c.buf, c.pos, (Long) value);
349→                        c.pos += 8;
350→                    }
351→                }
352→            }
353→            case FieldType.ArrayType at -> encodeArray(c, at.elementType(), (Object[]) value);
354→            case FieldType.VectorType vt -> encodeVector(c, vt, value);
355→            case FieldType.ObjectType ot -> encodeObject(c, ot, (JlsmDocument) value);
356→        }
357→    }
358→
359→    private static void encodeArray(Cursor c, FieldType elemType, Object[] arr) {
360→        writeVarInt(c, arr.length);
361→        // SIMD-accelerated paths for contiguous numeric types
362→        if (elemType == FieldType.Primitive.INT32) {
363→            encodeInt32Array(c, arr);
364→        } else if (elemType == FieldType.Primitive.INT64) {
365→            encodeInt64Array(c, arr);
366→        } else if (elemType == FieldType.Primitive.FLOAT32) {
367→            encodeFloat32Array(c, arr);
368→        } else if (elemType == FieldType.Primitive.FLOAT64) {
369→            encodeFloat64Array(c, arr);
370→        } else {
371→            for (Object elem : arr) {
372→                if (elem != null) {
373→                    encodeField(c, elemType, elem);
374→                }
375→            }
376→        }
377→    }
378→
379→    private static void encodeVector(Cursor c, FieldType.VectorType vt, Object value) {
380→        final int d = vt.dimensions();
381→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
382→            final float[] vec = (float[]) value;
383→            assert vec.length == d : "vector length must match dimensions";
384→            for (int i = 0; i < d; i++) {
385→                writeIntBE(c.buf, c.pos, Float.floatToRawIntBits(vec[i]));
386→                c.pos += 4;
387→            }
388→        } else {
389→            // FLOAT16 — stored as short[]
390→            final short[] vec = (short[]) value;
391→            assert vec.length == d : "vector length must match dimensions";
392→            for (int i = 0; i < d; i++) {
393→                writeShortBE(c.buf, c.pos, vec[i]);
394→                c.pos += 2;
395→            }
396→        }
397→    }
398→
399→    private static void encodeObject(Cursor c, FieldType.ObjectType ot, JlsmDocument sub) {
400→        final List<FieldDefinition> subFields = ot.fields();
401→        final Object[] subValues = sub.values();
402→        final int boolCount = countBoolFields(subFields);
403→        final int nullMaskBytes = (subFields.size() + 7) / 8;
404→        final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
405→
406→        final int nullMaskStart = c.pos;
407→        c.pos += nullMaskBytes;
408→        final int boolMaskStart = boolCount > 0 ? c.pos : -1;
409→        if (boolCount > 0) {
410→            c.pos += boolMaskBytes;
411→        }
412→
413→        buildNullMask(subFields, subValues, c.buf, nullMaskStart);
414→        if (boolCount > 0) {
415→            buildBoolMask(subFields, subValues, c.buf, boolMaskStart);
416→        }
417→        encodeFields(subFields, subValues, c);
418→    }
419→
420→    // =========================================================================
421→    // SIMD encode paths
422→    // =========================================================================
423→
424→    private static void encodeInt32Array(Cursor c, Object[] arr) {
425→        final int simdLen = BYTE_SPECIES.length(); // bytes per SIMD register
426→        // Only use SIMD if we have enough data (at least one full vector worth of 4-byte ints)
427→        final int simdElems = simdLen / 4; // number of int32 elements per SIMD operation
428→        int i = 0;
429→        if (arr.length >= simdElems && simdLen >= 4) {
430→            final int[] ints = new int[simdElems];
431→            while (i + simdElems <= arr.length) {
432→                for (int j = 0; j < simdElems; j++) {
433→                    ints[j] = (Integer) arr[i + j];
434→                }
435→                // Load as bytes (little-endian native), swap to big-endian
436→                final ByteVector bv = IntVector.fromArray(IntVector.SPECIES_PREFERRED, ints, 0)
437→                        .reinterpretAsBytes();
438→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
439→                c.pos += simdLen;
440→                i += simdElems;
441→            }
442→        }
443→        // Scalar remainder
444→        while (i < arr.length) {
445→            writeIntBE(c.buf, c.pos, (Integer) arr[i++]);
446→            c.pos += 4;
447→        }
448→    }
449→
450→    private static void encodeInt64Array(Cursor c, Object[] arr) {
451→        final int simdLen = BYTE_SPECIES.length();
452→        final int simdElems = simdLen / 8;
453→        int i = 0;
454→        if (arr.length >= simdElems && simdLen >= 8) {
455→            final long[] longs = new long[simdElems];
456→            while (i + simdElems <= arr.length) {
457→                for (int j = 0; j < simdElems; j++) {
458→                    longs[j] = (Long) arr[i + j];
459→                }
460→                final ByteVector bv = LongVector.fromArray(LongVector.SPECIES_PREFERRED, longs, 0)
461→                        .reinterpretAsBytes();
462→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
463→                c.pos += simdLen;
464→                i += simdElems;
465→            }
466→        }
467→        while (i < arr.length) {
468→            writeLongBE(c.buf, c.pos, (Long) arr[i++]);
469→            c.pos += 8;
470→        }
471→    }
