473→    private static void encodeFloat32Array(Cursor c, Object[] arr) {
474→        final int simdLen = BYTE_SPECIES.length();
475→        final int simdElems = simdLen / 4;
476→        int i = 0;
477→        if (arr.length >= simdElems && simdLen >= 4) {
478→            final float[] floats = new float[simdElems];
479→            while (i + simdElems <= arr.length) {
480→                for (int j = 0; j < simdElems; j++) {
481→                    floats[j] = (Float) arr[i + j];
482→                }
483→                final ByteVector bv = FloatVector
484→                        .fromArray(FloatVector.SPECIES_PREFERRED, floats, 0).reinterpretAsBytes();
485→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
486→                c.pos += simdLen;
487→                i += simdElems;
488→            }
489→        }
490→        while (i < arr.length) {
491→            writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) arr[i++]));
492→            c.pos += 4;
493→        }
494→    }
