496→    private static void encodeFloat64Array(Cursor c, Object[] arr) {
497→        final int simdLen = BYTE_SPECIES.length();
498→        final int simdElems = simdLen / 8;
499→        int i = 0;
500→        if (arr.length >= simdElems && simdLen >= 8) {
501→            final double[] doubles = new double[simdElems];
502→            while (i + simdElems <= arr.length) {
503→                for (int j = 0; j < simdElems; j++) {
504→                    doubles[j] = (Double) arr[i + j];
505→                }
