519→    // =========================================================================
520→    // Decode helpers
521→    // =========================================================================
522→
523→    private static Object decodeField(byte[] buf, Cursor cursor, FieldType type) {
524→        return switch (type) {
525→            case FieldType.Primitive p -> switch (p) {
526→                case STRING -> {
527→                    final int len = readVarInt(buf, cursor);
528→                    final String s = new String(buf, cursor.pos, len, StandardCharsets.UTF_8);
529→                    cursor.pos += len;
530→                    yield s;
531→                }
532→                case INT8 -> buf[cursor.pos++];
533→                case INT16 -> {
534→                    final short v = readShortBE(buf, cursor.pos);
535→                    cursor.pos += 2;
536→                    yield v;
537→                }
538→                case INT32 -> {
539→                    final int v = readIntBE(buf, cursor.pos);
540→                    cursor.pos += 4;
541→                    yield v;
542→                }
543→                case INT64 -> {
544→                    final long v = readLongBE(buf, cursor.pos);
545→                    cursor.pos += 8;
546→                    yield v;
547→                }
548→                case FLOAT16 -> {
549→                    final short v = readShortBE(buf, cursor.pos);
550→                    cursor.pos += 2;
551→                    yield v;
552→                }
553→                case FLOAT32 -> {
554→                    final float v = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
555→                    cursor.pos += 4;
556→                    yield v;
557→                }
558→                case FLOAT64 -> {
559→                    final double v = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
560→                    cursor.pos += 8;
561→                    yield v;
562→                }
563→                case BOOLEAN ->
564→                    throw new AssertionError("BOOLEAN should be handled via bool bitmask");
565→                case TIMESTAMP -> {
566→                    final long v = readLongBE(buf, cursor.pos);
567→                    cursor.pos += 8;
568→                    yield v;
569→                }
570→            };
571→            case FieldType.ArrayType at -> decodeArray(buf, cursor, at);
572→            case FieldType.VectorType vt -> decodeVector(buf, cursor, vt);
573→            case FieldType.ObjectType ot -> decodeObject(buf, cursor, ot);
574→        };
575→    }
576→
577→    private static Object[] decodeArray(byte[] buf, Cursor cursor, FieldType.ArrayType at) {
578→        final int count = readVarInt(buf, cursor);
579→        // SIMD-accelerated decode for contiguous numeric types
580→        final FieldType elemType = at.elementType();
581→        if (elemType == FieldType.Primitive.INT32) {
582→            return decodeInt32Array(buf, cursor, count);
583→        } else if (elemType == FieldType.Primitive.INT64) {
584→            return decodeInt64Array(buf, cursor, count);
585→        } else if (elemType == FieldType.Primitive.FLOAT32) {
586→            return decodeFloat32Array(buf, cursor, count);
587→        } else if (elemType == FieldType.Primitive.FLOAT64) {
588→            return decodeFloat64Array(buf, cursor, count);
589→        }
590→        final Object[] arr = new Object[count];
591→        for (int i = 0; i < count; i++) {
592→            arr[i] = decodeField(buf, cursor, elemType);
593→        }
594→        return arr;
595→    }
596→
597→    private static Object decodeVector(byte[] buf, Cursor cursor, FieldType.VectorType vt) {
598→        final int d = vt.dimensions();
599→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
600→            final float[] vec = new float[d];
601→            for (int i = 0; i < d; i++) {
602→                vec[i] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
603→                cursor.pos += 4;
604→            }
605→            return vec;
606→        } else {
607→            // FLOAT16 — return as short[]
608→            final short[] vec = new short[d];
609→            for (int i = 0; i < d; i++) {
610→                vec[i] = readShortBE(buf, cursor.pos);
611→                cursor.pos += 2;
612→            }
613→            return vec;
614→        }
615→    }
616→
617→    private static Object decodeObject(byte[] buf, Cursor cursor, FieldType.ObjectType ot) {
618→        final List<FieldDefinition> subFields = ot.fields();
619→        final int subFieldCount = subFields.size();
620→        final int subBoolCount = countBoolFields(subFields);
621→        final int nullMaskBytes = (subFieldCount + 7) / 8;
622→        final int boolMaskBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
623→
624→        final int nullMaskOffset = cursor.advance(nullMaskBytes);
625→        final int boolMaskOffset = subBoolCount > 0 ? cursor.advance(boolMaskBytes) : -1;
626→
627→        final Object[] subValues = new Object[subFieldCount];
628→        int boolIdx = 0;
629→        for (int i = 0; i < subFieldCount; i++) {
630→            final FieldDefinition fd = subFields.get(i);
631→            final boolean isNull = isNullBit(buf, nullMaskOffset, i);
632→            if (isNull) {
633→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
634→                    boolIdx++;
635→                }
636→                subValues[i] = null;
637→                continue;
638→            }
639→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
640→                assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
641→                subValues[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
642→                boolIdx++;
643→            } else {
644→                subValues[i] = decodeField(buf, cursor, fd.type());
645→            }
646→        }
647→
648→        // Synthesize a schema for the sub-document
649→        final JlsmSchema subSchema = ot.toSchema("nested", 0);
650→        return new JlsmDocument(subSchema, subValues);
651→    }
