657→    private static Object[] decodeInt32Array(byte[] buf, Cursor cursor, int count) {
658→        final Object[] result = new Object[count];
659→        final int simdLen = BYTE_SPECIES.length();
660→        final int simdElems = simdLen / 4;
661→        final int[] tmp = new int[simdElems];
662→        int i = 0;
663→        if (count >= simdElems && simdLen >= 4) {
664→            while (i + simdElems <= count) {
665→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
666→                        .reinterpretAsInts().intoArray(tmp, 0);
667→                for (int j = 0; j < simdElems; j++) {
668→                    result[i + j] = tmp[j];
669→                }
670→                cursor.pos += simdLen;
671→                i += simdElems;
672→            }
673→        }
674→        while (i < count) {
675→            result[i++] = readIntBE(buf, cursor.pos);
676→            cursor.pos += 4;
677→        }
678→        return result;
679→    }
