685→        final long[] tmp = new long[simdElems];
686→        int i = 0;
687→        if (count >= simdElems && simdLen >= 8) {
688→            while (i + simdElems <= count) {
689→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
690→                        .reinterpretAsLongs().intoArray(tmp, 0);
691→                for (int j = 0; j < simdElems; j++) {
692→                    result[i + j] = tmp[j];
693→                }
694→                cursor.pos += simdLen;
695→                i += simdElems;
696→            }
697→        }
698→        while (i < count) {
699→            result[i++] = readLongBE(buf, cursor.pos);
700→            cursor.pos += 8;
701→        }
702→        return result;
703→    }
