706→        final Object[] result = new Object[count];
707→        final int simdLen = BYTE_SPECIES.length();
708→        final int simdElems = simdLen / 4;
709→        final float[] tmp = new float[simdElems];
710→        int i = 0;
711→        if (count >= simdElems && simdLen >= 4) {
712→            while (i + simdElems <= count) {
713→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
714→                        .reinterpretAsFloats().intoArray(tmp, 0);
715→                for (int j = 0; j < simdElems; j++) {
716→                    result[i + j] = tmp[j];
717→                }
718→                cursor.pos += simdLen;
719→                i += simdElems;
720→            }
721→        }
722→        while (i < count) {
