729→    private static Object[] decodeFloat64Array(byte[] buf, Cursor cursor, int count) {
730→        final Object[] result = new Object[count];
731→        final int simdLen = BYTE_SPECIES.length();
732→        final int simdElems = simdLen / 8;
733→        final double[] tmp = new double[simdElems];
734→        int i = 0;
735→        if (count >= simdElems && simdLen >= 8) {
736→            while (i + simdElems <= count) {
737→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
