753→    // =========================================================================
754→    // Bitmask helpers
755→    // =========================================================================
756→
757→    private static void buildNullMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
758→            int offset) {
759→        for (int i = 0; i < fields.size(); i++) {
760→            if (values[i] == null) {
761→                buf[offset + i / 8] |= (byte) (1 << (i % 8));
762→            }
763→        }
764→    }
765→
766→    private static void buildBoolMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
767→            int offset) {
768→        int boolIdx = 0;
769→        for (int i = 0; i < fields.size(); i++) {
770→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
771→                final Object val = values[i];
772→                if (val instanceof Boolean b && b) {
773→                    buf[offset + boolIdx / 8] |= (byte) (1 << (boolIdx % 8));
774→                }
775→                boolIdx++;
776→            }
777→        }
778→    }
779→
780→    private static boolean isNullBit(byte[] buf, int maskOffset, int fieldIndex) {
781→        return (buf[maskOffset + fieldIndex / 8] & (1 << (fieldIndex % 8))) != 0;
782→    }
783→
784→    private static boolean isBoolBit(byte[] buf, int maskOffset, int boolIndex) {
785→        return (buf[maskOffset + boolIndex / 8] & (1 << (boolIndex % 8))) != 0;
786→    }
787→
788→    private static int countBoolFields(List<FieldDefinition> fields) {
789→        int count = 0;
790→        for (final FieldDefinition fd : fields) {
791→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
792→                count++;
793→            }
794→        }
795→        return count;
796→    }
