798→    // =========================================================================
799→    // VarInt (LEB128 unsigned)
800→    // =========================================================================
801→
802→    private static int varIntSize(int value) {
803→        assert value >= 0 : "VarInt value must be non-negative";
804→        if (value < 128) {
805→            return 1;
806→        }
807→        if (value < 16384) {
808→            return 2;
809→        }
810→        if (value < 2097152) {
811→            return 3;
812→        }
813→        if (value < 268435456) {
814→            return 4;
815→        }
816→        return 5;
817→    }
818→
819→    private static void writeVarInt(Cursor c, int value) {
820→        assert value >= 0 : "VarInt value must be non-negative";
821→        while (true) {
822→            if ((value & ~0x7F) == 0) {
823→                c.buf[c.pos++] = (byte) value;
824→                return;
825→            }
826→            c.buf[c.pos++] = (byte) ((value & 0x7F) | 0x80);
827→            value >>>= 7;
828→        }
829→    }
830→
831→    private static int readVarInt(byte[] buf, Cursor cursor) {
832→        int result = 0;
833→        int shift = 0;
834→        while (true) {
835→            final byte b = buf[cursor.pos++];
836→            result |= (b & 0x7F) << shift;
837→            if ((b & 0x80) == 0) {
838→                break;
839→            }
840→            shift += 7;
841→            assert shift <= 35 : "VarInt overflow — corrupt data";
842→        }
843→        return result;
844→    }
