846→    // =========================================================================
847→    // Primitive I/O
848→    // =========================================================================
849→
850→    private static void writeShortBE(byte[] buf, int offset, short value) {
851→        buf[offset] = (byte) (value >> 8);
852→        buf[offset + 1] = (byte) value;
853→    }
854→
855→    private static short readShortBE(byte[] buf, int offset) {
856→        return (short) ((buf[offset] << 8) | (buf[offset + 1] & 0xFF));
857→    }
858→
859→    private static void writeIntBE(byte[] buf, int offset, int value) {
860→        buf[offset] = (byte) (value >> 24);
861→        buf[offset + 1] = (byte) (value >> 16);
862→        buf[offset + 2] = (byte) (value >> 8);
863→        buf[offset + 3] = (byte) value;
864→    }
865→
866→    private static int readIntBE(byte[] buf, int offset) {
867→        return ((buf[offset] & 0xFF) << 24) | ((buf[offset + 1] & 0xFF) << 16)
868→                | ((buf[offset + 2] & 0xFF) << 8) | (buf[offset + 3] & 0xFF);
869→    }
870→
871→    private static void writeLongBE(byte[] buf, int offset, long value) {
872→        buf[offset] = (byte) (value >> 56);
873→        buf[offset + 1] = (byte) (value >> 48);
874→        buf[offset + 2] = (byte) (value >> 40);
875→        buf[offset + 3] = (byte) (value >> 32);
876→        buf[offset + 4] = (byte) (value >> 24);
877→        buf[offset + 5] = (byte) (value >> 16);
878→        buf[offset + 6] = (byte) (value >> 8);
879→        buf[offset + 7] = (byte) value;
880→    }
881→
882→    private static long readLongBE(byte[] buf, int offset) {
883→        return ((long) (buf[offset] & 0xFF) << 56) | ((long) (buf[offset + 1] & 0xFF) << 48)
884→                | ((long) (buf[offset + 2] & 0xFF) << 40) | ((long) (buf[offset + 3] & 0xFF) << 32)
885→                | ((long) (buf[offset + 4] & 0xFF) << 24) | ((long) (buf[offset + 5] & 0xFF) << 16)
886→                | ((long) (buf[offset + 6] & 0xFF) << 8) | ((long) (buf[offset + 7] & 0xFF));
887→    }
