889→    // =========================================================================
890→    // Heap fast path
891→    // =========================================================================
892→
893→    /** View of a byte array with an offset — enables zero-copy for heap-backed segments. */
894→    private record ByteArrayView(byte[] data, int offset) {
895→    }
896→
897→    /**
898→     * Extracts a byte array view from a {@link MemorySegment}. For heap-backed segments (created
899→     * via {@code MemorySegment.ofArray(byte[])}), returns the backing array directly — zero-copy.
900→     * For off-heap or sliced segments, falls back to {@code toArray()}.
901→     */
902→    private static ByteArrayView extractBytes(MemorySegment segment) {
903→        Optional<Object> heapBase = segment.heapBase();
904→        if (heapBase.isPresent() && heapBase.get() instanceof byte[] data
905→                && segment.byteSize() == data.length) {
906→            // Full array — offset is 0 for MemorySegment.ofArray(byte[])
907→            return new ByteArrayView(data, 0);
908→        } else {
909→            byte[] data = segment.toArray(ValueLayout.JAVA_BYTE);
910→            return new ByteArrayView(data, 0);
911→        }
912→    }
