914→    // =========================================================================
915→    // Cursor
916→    // =========================================================================
917→
918→    /** Mutable position cursor for sequential byte-array I/O. */
919→    private static final class Cursor {
920→
921→        final byte[] buf;
922→        int pos;
923→
924→        Cursor(byte[] buf, int pos) {
925→            this.buf = buf;
926→            this.pos = pos;
927→        }
928→
929→        /** Advances position by {@code n} bytes and returns the old position. */
930→        int advance(int n) {
931→            final int old = pos;
932→            pos += n;
933→            return old;
934→        }
935→    }
936→}
