  3→import static org.junit.jupiter.api.Assertions.*;
  4→
  5→import java.io.IOException;
  6→import java.lang.foreign.Arena;
  7→import java.lang.foreign.MemorySegment;
  8→import java.util.List;
  9→
 10→import jlsm.table.internal.IndexRegistry;
 11→import org.junit.jupiter.api.Test;
 12→import org.junit.jupiter.api.io.TempDir;
 13→
 14→import java.nio.file.Path;
 15→
 16→class IndexRegistryTest {
 17→
 18→    @TempDir
 19→    Path tempDir;
 20→
 21→    private JlsmSchema buildSchema() {
 22→        return JlsmSchema.builder("test", 1).field("name", FieldType.string())
 23→                .field("age", FieldType.int32()).field("email", FieldType.string())
 24→                .field("active", FieldType.boolean_()).build();
 25→    }
 26→
 27→    private MemorySegment stringKey(String key) {
 28→        byte[] bytes = key.getBytes(java.nio.charset.StandardCharsets.UTF_8);
 29→        MemorySegment seg = Arena.ofAuto().allocate(bytes.length);
 30→        seg.copyFrom(MemorySegment.ofArray(bytes));
 31→        return seg;
 32→    }
 33→
 34→    @Test
 35→    void testValidatesAgainstSchema() throws IOException {
 36→        var schema = buildSchema();
 37→        var defs = List.of(new IndexDefinition("name", IndexType.EQUALITY),
 38→                new IndexDefinition("age", IndexType.RANGE));
 39→
 40→        var registry = new IndexRegistry(schema, defs);
 41→        assertFalse(registry.isEmpty());
 42→        registry.close();
 43→    }
 44→
 45→    @Test
 46→    void testNonexistentFieldThrowsIae() {
 47→        var schema = buildSchema();
 48→        var defs = List.of(new IndexDefinition("nonexistent", IndexType.EQUALITY));
 49→
 50→        assertThrows(IllegalArgumentException.class, () -> new IndexRegistry(schema, defs),
 51→                "Should reject index on field not in schema");
 52→    }
 53→
 54→    @Test
 55→    void testIncompatibleTypeThrowsIae() {
 56→        var schema = buildSchema();
 57→        // RANGE on BOOLEAN should be rejected — boolean is not naturally ordered
 58→        var defs = List.of(new IndexDefinition("active", IndexType.RANGE));
 59→
 60→        assertThrows(IllegalArgumentException.class, () -> new IndexRegistry(schema, defs),
 61→                "Should reject RANGE index on BOOLEAN field");
 62→    }
 63→
 64→    @Test
 65→    void testRoutesInsert() throws IOException {
 66→        var schema = buildSchema();
 67→        var defs = List.of(new IndexDefinition("name", IndexType.EQUALITY),
 68→                new IndexDefinition("age", IndexType.RANGE));
 69→        var registry = new IndexRegistry(schema, defs);
 70→
 71→        var doc = JlsmDocument.of(schema, "name", "Alice", "age", 30, "email", "user@example.com",
 72→                "active", true);
 73→        registry.onInsert(stringKey("pk1"), doc);
 74→
 75→        // Verify name index got the entry
 76→        var nameIndex = registry.findIndex(new Predicate.Eq("name", "Alice"));
 77→        assertNotNull(nameIndex, "Should find index for name equality");
 78→
 79→        // Verify age index got the entry
 80→        var ageIndex = registry.findIndex(new Predicate.Gt("age", 25));
 81→        assertNotNull(ageIndex, "Should find index for age range");
 82→
 83→        registry.close();
 84→    }
 85→
 86→    @Test
 87→    void testRoutesUpdate() throws IOException {
 88→        var schema = buildSchema();
 89→        var defs = List.of(new IndexDefinition("name", IndexType.EQUALITY));
 90→        var registry = new IndexRegistry(schema, defs);
 91→
 92→        var oldDoc = JlsmDocument.of(schema, "name", "Alice", "age", 30, "email", "user@example.com",
 93→                "active", true);
 94→        var newDoc = JlsmDocument.of(schema, "name", "Carol", "age", 30, "email", "user@example.com",
 95→                "active", true);
 96→
 97→        registry.onInsert(stringKey("pk1"), oldDoc);
 98→        registry.onUpdate(stringKey("pk1"), oldDoc, newDoc);
 99→
100→        // The name index should now have Carol, not Alice
101→        // (Verification via findIndex + lookup if available)
102→        assertNotNull(registry.findIndex(new Predicate.Eq("name", "Carol")));
103→
104→        registry.close();
105→    }
106→
107→    @Test
108→    void testRoutesDelete() throws IOException {
109→        var schema = buildSchema();
110→        var defs = List.of(new IndexDefinition("name", IndexType.EQUALITY));
111→        var registry = new IndexRegistry(schema, defs);
112→
113→        var doc = JlsmDocument.of(schema, "name", "Alice", "age", 30, "email", "user@example.com",
114→                "active", true);
115→        registry.onInsert(stringKey("pk1"), doc);
116→        registry.onDelete(stringKey("pk1"), doc);
117→
118→        // After delete, the index should not contain the entry
119→        // (Verification relies on lookup returning empty results)
120→        registry.close();
121→    }
122→
123→    @Test
124→    void testFindIndexReturnsNullForUnmatched() throws IOException {
125→        var schema = buildSchema();
126→        var defs = List.of(new IndexDefinition("name", IndexType.EQUALITY));
127→        var registry = new IndexRegistry(schema, defs);
128→
129→        // No index on "age", so should return null
130→        assertNull(registry.findIndex(new Predicate.Gt("age", 30)),
131→                "Should return null for field without index");
132→
133→        registry.close();
134→    }
135→
136→    @Test
137→    void testIsEmpty() throws IOException {
138→        var schema = buildSchema();
139→        var emptyRegistry = new IndexRegistry(schema, List.of());
140→        assertTrue(emptyRegistry.isEmpty());
141→        emptyRegistry.close();
142→
143→        var nonEmptyRegistry = new IndexRegistry(schema,
144→                List.of(new IndexDefinition("name", IndexType.EQUALITY)));
145→        assertFalse(nonEmptyRegistry.isEmpty());
146→        nonEmptyRegistry.close();
147→    }
148→}
